PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "shop_customuser_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "shop_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "shop_customuser_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "shop_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "shop_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "shop_customuser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "fio" varchar(100) NOT NULL, "role" varchar(32) NOT NULL);
CREATE TABLE IF NOT EXISTS "shop_kategoriatovara" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "shop_postavschik" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "shop_proizvoditel" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "shop_punktvidachi" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "shop_tovar" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "artikul" varchar(20) NOT NULL UNIQUE, "name" varchar(40) NOT NULL, "cena" integer NOT NULL, "skidka" integer NOT NULL, "na_sklade" integer NOT NULL, "opisanie" varchar(400) NOT NULL, "kategoria_id" bigint NOT NULL REFERENCES "shop_kategoriatovara" ("id") DEFERRABLE INITIALLY DEFERRED, "postavschik_id" bigint NOT NULL REFERENCES "shop_postavschik" ("id") DEFERRABLE INITIALLY DEFERRED, "proizvoditel_id" bigint NOT NULL REFERENCES "shop_proizvoditel" ("id") DEFERRABLE INITIALLY DEFERRED, "foto" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "shop_statuszakaza" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "shop_tovarvzakaze" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "kolichestvo" integer NOT NULL, "tovar_id" bigint NOT NULL REFERENCES "shop_tovar" ("id") DEFERRABLE INITIALLY DEFERRED, "zakaz_id" integer NOT NULL REFERENCES "shop_zakaz" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "shop_zakaz" ("id" integer unsigned NOT NULL PRIMARY KEY CHECK ("id" >= 0), "data_zakaza" date NOT NULL, "data_dostavki" date NOT NULL, "fio_klienta" varchar NOT NULL, "kod" integer NOT NULL UNIQUE, "punkt_vidachi_id" bigint NOT NULL REFERENCES "shop_punktvidachi" ("id") DEFERRABLE INITIALLY DEFERRED, "status_id" bigint NOT NULL REFERENCES "shop_statuszakaza" ("id") DEFERRABLE INITIALLY DEFERRED);
PRAGMA writable_schema=ON;
